export function localizeModel(locale){
 traits.forEach((trait,i)=>{Object.assign(trait,structuredClone(original.traits[i]));if(locale==='hi'){const [name,short,low,high,intro]=labels[i];Object.assign(trait,{name,short,low,high,intro,profiles:profiles[i].map(([title,meaning,strength,watch,step])=>({title,meaning,strength,watch,step}))})}});
 questions.forEach((question,i)=>{Object.assign(question,structuredClone(original.questions[i]));if(locale==='hi'){const row=Math.floor(i/5),dim=question.dim;question.text=statements[dim][row];if(question.options){question.scene=scenes[dim];question.options=[...options[dim]]}}});
 agreement.splice(0,5,...(locale==='hi'?['बिल्कुल असहमत','असहमत','न सहमत, न असहमत','सहमत','पूरी तरह सहमत']:original.agreement));
}
